/**
 * @name Insecure JWT validation
 * @description JWT decoding without proper signature verification
 * @kind path-problem
 * @problem.severity error
 * @id py/jwt-validation
 * @tags security
 *        external/cwe/cwe-345
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module JwtConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // JWT decode calls without verification
    sink = API::moduleImport("jwt").getMember(["decode", "decode_complete"]).getACall().getArg(0)
  }
}

module JwtFlow = TaintTracking::Global<JwtConfig>;
import JwtFlow::PathGraph

from JwtFlow::PathNode source, JwtFlow::PathNode sink
where JwtFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "JWT token from user input passed to decode without verification from $@.", source.getNode(), "user input"

/**
 * @name Command injection with data flow tracking
 * @description User input reaching command execution functions
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Command execution sinks
    sink = API::moduleImport("os").getMember(["system", "popen", "popen2", "popen3", "popen4"]).getACall().getArg(0) or
    sink = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "Popen"]).getACall().getArg(0)
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"
